import { INCREMENTAL_STATE_STORAGE_KEY } from './incrementalTranslationPayload';

export const buildIncrementalStateSnapshot = ({
  active,
  archiveInfo,
  batchSizeLimit,
  checkpointFound,
  checkpointInfo,
  completionSource,
  concurrencyLimit,
  currentTaskId,
  currentTaskMode,
  customSourcePath,
  embeddedWorkshopBatchSize,
  embeddedWorkshopConcurrency,
  embeddedWorkshopEnabled,
  embeddedWorkshopFollowPrimary,
  embeddedWorkshopModel,
  embeddedWorkshopProvider,
  embeddedWorkshopRpm,
  errorKey,
  executing,
  finalSummary,
  loading,
  logs,
  progress,
  progressInfo,
  rpmLimit,
  scanResults,
  selectedLangs,
  selectedModel,
  selectedProject,
  selectedProvider,
  showResumeDetails,
  showWorkshopSettings,
  useResume,
}) => ({
  active,
  loading,
  selectedProject,
  selectedProvider,
  selectedModel,
  customSourcePath,
  selectedLangs,
  batchSizeLimit,
  concurrencyLimit,
  rpmLimit,
  archiveInfo,
  scanResults,
  errorKey,
  executing,
  progress,
  progressInfo,
  logs,
  finalSummary,
  checkpointFound,
  checkpointInfo,
  useResume,
  showResumeDetails,
  embeddedWorkshopEnabled,
  embeddedWorkshopFollowPrimary,
  embeddedWorkshopProvider,
  embeddedWorkshopModel,
  embeddedWorkshopBatchSize,
  embeddedWorkshopConcurrency,
  embeddedWorkshopRpm,
  showWorkshopSettings,
  currentTaskId,
  currentTaskMode,
  completionSource,
});

export const readIncrementalStateSnapshot = (storage = sessionStorage) => {
  const rawState = storage.getItem(INCREMENTAL_STATE_STORAGE_KEY);
  return rawState ? JSON.parse(rawState) : null;
};

export const writeIncrementalStateSnapshot = (snapshot, storage = sessionStorage) => {
  storage.setItem(INCREMENTAL_STATE_STORAGE_KEY, JSON.stringify(snapshot));
};
